import pytest
from operations import Calculator

@pytest.fixture
def calc():
    return Calculator()

def test_add(calc):
    assert calc.add(5, 3) == 8
    assert calc.add(-1, 1) == 0

def test_subtract(calc):
    assert calc.subtract(10, 4) == 6
    assert calc.subtract(0, 5) == -5

def test_multiply(calc):
    assert calc.multiply(3, 3) == 9
    assert calc.multiply(-2, 4) == -8

def test_divide(calc):
    assert calc.divide(10, 2) == 5
    assert calc.divide(5, 2) == 2.5

def test_divide_zero_raises(calc):
    with pytest.raises(ValueError, match="Division by zero"):
        calc.divide(10, 0)

def test_history_records(calc):
    calc.add(1, 2)
    calc.multiply(3, 4)
    history = calc.get_history()
    assert len(history) == 2
    assert history[0] == ("add", 1.0, 2.0, 3.0)
    assert history[1] == ("multiply", 3.0, 4.0, 12.0)

def test_history_is_copy(calc):
    calc.add(1, 1)
    history = calc.get_history()
    history.append(("fake", 0, 0, 0))
    assert len(calc.get_history()) == 1

def test_clear_history(calc):
    calc.add(1, 1)
    calc.clear_history()
    assert len(calc.get_history()) == 0

